const D = { energy:.65, scale:1, density:.55, speed:1, hue:280, morph:.7, trail:.5, x:.5, y:.5, style:'plasma', act:'breathe', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const st = P.style, ink = (st==='ink');
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.ba = -1.7 + fr(1)*1.3;
  S.bb =  1.2 + fr(2)*1.5;
  S.bc =  0.7 + fr(3)*1.1;
  S.bd =  0.6 + fr(4)*1.2;
  S.hbase = fr(5)*360;
  S.rot0 = fr(6)*6.283;
}
const intn = (K.intensity!=null?K.intensity:0.6);
const expo = 0.4 + P.energy*1.15;
let morphAmp = P.morph, breath = 0.8 + K.swell*0.4;
if (P.act==='surge') { morphAmp = P.morph*(0.55+intn*0.9); breath = 0.5+intn*1.1; }
else if (P.act==='drift') { morphAmp = P.morph*0.7; breath = 0.85; }
const kick = K.pulse*0.5 + A.bass*0.7;
// crisper cloud (faster trail fade) so the spinning/drifting cloud registers as motion
let fadeA = (20 + P.trail*22) - kick*4; if (fadeA < 9) fadeA = 9;
noStroke(); blendMode(BLEND);
if (st==='ink') fill(34,10,90,fadeA+3);
else if (st==='blueprint') fill(218,72,15,fadeA);
else if (st==='thermal') fill(250,32,4,fadeA);
else if (st==='wire') fill(210,45,4,fadeA);
else fill(248,58,5,fadeA);
rect(0,0,width,height);
// slow parameter DRIFT (base coeffs wander over minutes) + faster morph oscillation
const T = K.t*P.speed;
const drift = Math.sin(K.t*0.021)*0.35 + Math.cos(K.t*0.013)*0.25;
const a = S.ba + drift*0.6 + Math.sin(T*0.17)*morphAmp*1.2;
const b = S.bb - drift*0.5 + Math.cos(T*0.13)*morphAmp*1.1;
const c = S.bc + Math.sin(T*0.097)*morphAmp*0.9;
const d = S.bd + Math.cos(T*0.079)*morphAmp*1.0;
const sc = (u/4.6) * P.scale;
const glow = 0.4 + P.energy*0.6 + intn*0.35 + A.rms*1.2;
const hueDrift = K.t*9 + S.hbase + P.hue;
const dotSz = (2.1 + P.energy*2.2);
const alphaMul = expo*3.0;
const N = Math.floor((380 + P.density*1420) * (0.6 + P.energy*0.7) * (st==='wire'?0.55:1) * Math.min(1.2, breath));
push();
// continuous precession of the WHOLE cloud + gentle position drift across the frame
const orbT = K.t*0.42*P.speed;
const px0 = P.x*width + Math.cos(orbT)*u*0.24 + A.lowmid*u*0.05;
const py0 = P.y*height + Math.sin(orbT*0.83)*u*0.20;
translate(px0, py0);
rotate(S.rot0 + K.t*0.16*P.speed + K.swell*0.15);
if (!ink && st!=='blueprint') blendMode(ADD);
if (st==='wire'){ noFill(); strokeWeight(0.8 + P.energy*1.4); } else noStroke();
let x=0.1, y=0.1, px=null, py=null;
for (let i=0;i<N;i++){
  const nx = Math.sin(a*y) + c*Math.cos(a*x);
  const ny = Math.sin(b*x) + d*Math.cos(b*y);
  x=nx; y=ny;
  const sx=x*sc, sy=y*sc;
  if (st==='plasma'){
    fill((hueDrift + i*0.03)%360, 78, Math.min(100,55+glow*40), 7*alphaMul);
    ellipse(sx,sy,dotSz,dotSz);
  } else if (st==='thermal'){
    const r = Math.min(1, Math.sqrt(x*x+y*y)/2.3);
    fill((250 - r*250 + 360)%360, 88, Math.min(100,42+r*56), 8*alphaMul);
    ellipse(sx,sy,dotSz+0.2,dotSz+0.2);
  } else if (st==='wire'){
    if (px!==null){ stroke((hueDrift + i*0.02)%360, 62, 88, Math.min(60,11*alphaMul)); line(px,py,sx,sy); }
    px=sx; py=sy;
  } else if (st==='blueprint'){
    fill(196, 66, 94, Math.min(80,20*alphaMul)); ellipse(sx,sy,dotSz-0.1,dotSz-0.1);
  } else {
    const j = fr(i);
